type Props = ComponentProps<typeof OnboardingHint>;
function Example({ anchor, visible, onClose, dataTestId, onButtonClick }: {
    anchor: Props['children']; visible: Props['visible'];
    onClose: NonNullable<Props['onClose']>; dataTestId: NonNullable<Props['dataTestId']>;
    onButtonClick: NonNullable<Props['onButtonClick']>;
}) {
    if (!dataTestId.trim()) throw new Error('Нужен dataTestId приложения');
    return <OnboardingHint position="right" visible={visible} onClose={onClose} dataTestId={dataTestId}
        tooltipContent={"Tooltip text."}
        buttonText={"Label"} onButtonClick={onButtonClick}
    >{anchor}</OnboardingHint>;
}

